  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1120;
      --panel: rgba(15, 23, 42, 0.92);
      --panel-border: rgba(148, 163, 184, 0.2);
      --text: #e2e8f0;
      --muted: #94a3b8;
      --input: #111827;
      --input-border: #334155;
      --input-focus: #38bdf8;
      --error: #fda4af;
      --error-strong: #fb7185;
      --success-bg: rgba(34, 197, 94, 0.14);
      --success-border: rgba(74, 222, 128, 0.45);
      --success-text: #bbf7d0;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 24px;
      font-family: Arial, sans-serif;
      background:
        radial-gradient(circle at top, rgba(56, 189, 248, 0.16), transparent 32%),
        linear-gradient(180deg, #020617 0%, #0f172a 100%);
      color: var(--text);
    }

    .support-card {
      width: min(100%, 520px);
      padding: 32px;
      border: 1px solid var(--panel-border);
      border-radius: 20px;
      background: var(--panel);
      backdrop-filter: blur(16px);
      box-shadow: 0 24px 60px rgba(2, 6, 23, 0.45);
    }

    h1 {
      margin: 0 0 12px;
      font-size: 1.95rem;
      line-height: 1.15;
    }

    .intro {
      margin: 0 0 24px;
      color: var(--muted);
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 18px;
    }

    .form-field {
      display: grid;
      gap: 8px;
    }

    label {
      font-weight: 700;
      font-size: 0.95rem;
    }

    input {
      width: 100%;
      padding: 14px 16px;
      border: 1px solid var(--input-border);
      border-radius: 12px;
      background: var(--input);
      color: var(--text);
      font: inherit;
      transition: border-color 150ms ease, box-shadow 150ms ease, transform 150ms ease;
    }

    input::placeholder {
      color: #64748b;
    }

    input:focus {
      outline: none;
      border-color: var(--input-focus);
      box-shadow: 0 0 0 4px rgba(56, 189, 248, 0.18);
      transform: translateY(-1px);
    }

    input[aria-invalid="true"] {
      border-color: var(--error-strong);
      box-shadow: 0 0 0 4px rgba(251, 113, 133, 0.14);
    }

    .helper-text,
    .error-message,
    .success-message {
      font-size: 0.92rem;
      line-height: 1.45;
    }

    .helper-text {
      color: var(--muted);
    }

    .error-message {
      min-height: 1.35em;
      color: var(--error);
    }

    .success-message {
      display: none;
      padding: 12px 14px;
      border: 1px solid var(--success-border);
      border-radius: 12px;
      background: var(--success-bg);
      color: var(--success-text);
    }

    .success-message.is-visible {
      display: block;
    }

    button {
      border: 0;
      border-radius: 12px;
      padding: 14px 18px;
      font: inherit;
      font-weight: 700;
      color: #020617;
      background: linear-gradient(135deg, #67e8f9 0%, #38bdf8 100%);
      cursor: pointer;
      transition: transform 150ms ease, box-shadow 150ms ease, filter 150ms ease;
      box-shadow: 0 18px 30px rgba(14, 165, 233, 0.28);
    }

    button:hover {
      filter: brightness(1.04);
      transform: translateY(-1px);
    }

    button:focus-visible {
      outline: 3px solid rgba(103, 232, 249, 0.45);
      outline-offset: 3px;
    }

    @media (max-width: 560px) {
      .support-card {
        padding: 24px;
      }
    }
  </style>
</head>
<body>
  <main class="support-card">
    <h1>Contact support</h1>
    <p class="intro">Send us your details and a member of our support team will follow up as soon as possible.</p>

    <form id="support-form" novalidate>
      <div class="form-field">
        <label for="fullName">Full name</label>
        <input
          id="fullName"
          name="fullName"
          type="text"
          autocomplete="name"
          placeholder="Jordan Lee"
          required
          aria-describedby="fullName-error"
        >
        <div id="fullName-error" class="error-message" aria-live="polite"></div>
      </div>

      <div class="form-field">
        <label for="email">Email address</label>
        <input
          id="email"
          name="email"
          type="email"
          autocomplete="email"
          placeholder="jordan@example.com"
          required
          aria-describedby="email-error"
        >
        <div id="email-error" class="error-message" aria-live="polite"></div>
      </div>

      <div class="form-field">
        <label for="phone">Phone number</label>
        <input
          id="phone"
          name="phone"
          type="tel"
          autocomplete="tel"
          placeholder="(555) 123-4567"
          aria-describedby="phone-help phone-error"
        >
        <div id="phone-help" class="helper-text">Optional. Use digits, spaces, dashes, or parentheses, for example: (555) 123-4567 or +1 555-123-4567.</div>
        <div id="phone-error" class="error-message" aria-live="polite"></div>
      </div>

      <button type="submit">Submit</button>
      <div id="form-success" class="success-message" aria-live="polite">Your message is ready to be sent. Our support team will contact you soon.</div>
    </form>
  </main>

  <script>
    const form = document.getElementById("support-form");
    const successMessage = document.getElementById("form-success");

    const fields = {
      fullName: {
        input: document.getElementById("fullName"),
        error: document.getElementById("fullName-error"),
        validate(value) {
          if (!value.trim()) {
            return "Full name is required.";
          }
          return "";
        }
      },
      email: {
        input: document.getElementById("email"),
        error: document.getElementById("email-error"),
        validate(value) {
          const trimmedValue = value.trim();
          if (!trimmedValue) {
            return "Email address is required.";
          }
          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailPattern.test(trimmedValue)) {
            return "Enter a valid email address.";
          }
          return "";
        }
      },
      phone: {
        input: document.getElementById("phone"),
        error: document.getElementById("phone-error"),
        validate(value) {
          const trimmedValue = value.trim();
          if (!trimmedValue) {
            return "";
          }
          const phonePattern = /^\+?[0-9()\-\s]{7,20}$/;
          if (!phonePattern.test(trimmedValue)) {
            return "Enter a valid phone number using digits and standard separators.";
          }
          return "";
        }
      }
    };

    function showError(fieldConfig, message) {
      fieldConfig.error.textContent = message;
      fieldConfig.input.setAttribute("aria-invalid", message ? "true" : "false");
    }

    function validateField(fieldConfig) {
      const message = fieldConfig.validate(fieldConfig.input.value);
      showError(fieldConfig, message);
      return !message;
    }

    Object.values(fields).forEach((fieldConfig) => {
      fieldConfig.input.addEventListener("blur", () => {
        validateField(fieldConfig);
      });

      fieldConfig.input.addEventListener("input", () => {
        if (fieldConfig.error.textContent) {
          validateField(fieldConfig);
        }
        successMessage.classList.remove("is-visible");
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const allValid = Object.values(fields).every((fieldConfig) => validateField(fieldConfig));
      successMessage.classList.toggle("is-visible", allValid);
    });
  </script>
</body>
</html>
